const assert = require('node:assert/strict');
const { OrderHandler } = require('../.build/handler');
const { OrderRepository } = require('../.build/repository');

function mk(list) { return list.map(([id, createdAt, tenant]) => ({ id, tenant, createdAt, total: 0 })); }
function page(repoRows, req) {
  const repo = new OrderRepository(repoRows);
  const before = JSON.stringify(repoRows);
  const res = new OrderHandler(repo).list(req);
  assert.equal(JSON.stringify(repoRows), before, 'must not mutate input rows/array');
  return res;
}

// Ascending sort by createdAt then id; tenant filter; limit; nextCursor chain.
let rows = mk([['a2', '2026-01-01', 't'], ['b1', '2026-01-01', 't'], ['a1', '2026-01-01', 't'],
  ['z', '2025-12-31', 't'], ['other', '2026-01-01', 'u'], ['last', '2026-03-01', 't']]);
let p1 = page(rows, { tenant: 't', limit: 2 });
assert.deepEqual(p1.items.map(x => x.id), ['z', 'a1']);
assert.equal(p1.nextCursor, '2026-01-01|a1');
const p2 = page(rows, { tenant: 't', limit: 2, cursor: p1.nextCursor });
assert.deepEqual(p2.items.map(x => x.id), ['a2', 'b1']);
assert.equal(p2.nextCursor, '2026-01-01|b1');
const p3 = page(rows, { tenant: 't', limit: 2, cursor: p2.nextCursor });
assert.deepEqual(p3.items.map(x => x.id), ['last']);
assert.equal(p3.nextCursor, null); // no further matching order
// cursor of last page resumes to empty
assert.deepEqual(page(rows, { tenant: 't', limit: 5, cursor: '2026-03-01|last' }), { items: [], nextCursor: null });

// Cursor row deleted: resumes strictly after the pair regardless.
rows = mk([['a', '2026-01-01', 't'], ['c', '2026-01-01', 't'], ['d', '2026-01-02', 't']]);
assert.deepEqual(page(rows, { tenant: 't', limit: 10, cursor: '2026-01-01|b' }).items.map(x => x.id), ['c', 'd']);

// Cursor pair belongs to another tenant: the cursor is a pure key compared only
// against this tenant's filtered, sorted rows (that row is not required to exist).
// A foreign pair sorting AFTER the tenant's rows -> empty page (nothing to resume);
// a foreign pair sorting BEFORE -> the tenant's rows all follow normally.
rows = mk([['a', '2026-01-01', 't'], ['b', '2026-01-02', 't'], ['x', '2026-01-03', 'u']]);
assert.deepEqual(page(rows, { tenant: 't', limit: 10, cursor: '2026-01-03|x' }).items.map(x => x.id), []);
assert.deepEqual(page(rows, { tenant: 't', limit: 10, cursor: '2025-01-01|x' }).items.map(x => x.id), ['a', 'b']);
// foreign cursor interleaved between the tenant's rows: only later tenant rows return
assert.deepEqual(page(rows, { tenant: 't', limit: 10, cursor: '2026-01-01|x' }).items.map(x => x.id), ['b']);

// Equal-date orders never skipped/repeated across pages.
rows = mk([['p', '2026-01-01', 't'], ['q', '2026-01-01', 't'], ['r', '2026-01-01', 't']]);
const q1 = page(rows, { tenant: 't', limit: 1 });
const q2 = page(rows, { tenant: 't', limit: 1, cursor: q1.nextCursor });
const q3 = page(rows, { tenant: 't', limit: 1, cursor: q2.nextCursor });
assert.deepEqual([q1, q2, q3].map(p => p.items[0] && p.items[0].id), ['p', 'q', 'r']);
assert.equal(q3.nextCursor, null);

// Page containing exactly the last item -> nextCursor null even when equal-date peer exists elsewhere.
rows = mk([['a', '2026-01-01', 't'], ['b', '2026-01-02', 't']]);
assert.equal(page(rows, { tenant: 't', limit: 1, cursor: '2026-01-01|a' }).nextCursor, null);

// No cursor + limit behavior preserved (limit beyond available, limit 1).
rows = mk([['a', '2026-01-01', 't'], ['b', '2026-01-02', 't']]);
assert.deepEqual(page(rows, { tenant: 't', limit: 100 }).items.map(x => x.id), ['a', 'b']);

// Invalid requests.
const bad = [
  () => page(rows, { tenant: '', limit: 1 }),
  () => page(rows, { tenant: 't', limit: 0 }),
  () => page(rows, { tenant: 't', limit: 101 }),
  () => page(rows, { tenant: 't', limit: 1.5 }),
  () => page(rows, { tenant: 't', limit: NaN }),
  () => page(rows, { tenant: 't', limit: Infinity }),
  () => page(rows, { tenant: 't', limit: 1, cursor: '' }),
  () => page(rows, { tenant: 't', limit: 1, cursor: 'nosep' }),
  () => page(rows, { tenant: 't', limit: 1, cursor: 'a|b|c' }),
  () => page(rows, { tenant: 't', limit: 1, cursor: '2026-01-01|' }),
  () => page(rows, { tenant: 't', limit: 1, cursor: '|b' }),
  () => page(rows, { tenant: 't', limit: 1, cursor: '||' }),
];
for (const fn of bad) assert.throws(fn, /^Error: invalid request$/);

// Cursor equality on both parts only resumes past that exact pair.
rows = mk([['b', '2026-01-01', 't'], ['c', '2026-01-01', 't']]);
assert.deepEqual(page(rows, { tenant: 't', limit: 10, cursor: '2026-01-01|b' }).items.map(x => x.id), ['c']);

console.log('cursor checks OK');

